# Docusaurus Plugin Zooming

This plugin uses the [`Zooming`](https://www.npmjs.com/package/zooming) library to allow for zoom in/out on images in your documentation.

## Install

```shell
npm install docusaurus-plugin-zooming
```

## Usage

Update `docusaurus.config.js` to enable the plugin and include its default configuration:

```js
  const config = {
    // ...other config

    plugins: [
      'docusaurus-plugin-zooming',
      // ...other plugins
    ],

    themeConfig: {
      // ...other themeConfig

      zooming: {
        selector: '.markdown img',
        delay: 500,
        background: {
          light: 'rgba(101,108,133,0.8)',
          dark: 'rgba(9,10,17,0.8)'
        },
        options: {
          // See the docs of zooming for all available options: https://github.com/francoischalifour/medium-zoom#usage
        }
      },
    },
  }

  module.exports = config;
```

## Configuration

This plugin allows you to configure the following options:

| Option        | Description                                                                                      | Default Value                                                                                         |
|---------------|--------------------------------------------------------------------------------------------------|------------------------------------------------------------------------------------------------------|
| `selector`    | (optional) The selector for zoomable image elements.                                          | `.markdown img`                                                                                      |
| `delay`    | (optional) Make imgaes zoomable with delay after entering a page                                          | `500`                                                                                      |
| `background`  | (optional) The background color to use for the zoomed image.                                     | `{ light: 'rgb(255, 255, 255, 0.9)', dark: 'rgb(50, 50, 50, 0.9)' }`                                           |
| `options`      | (optional) The configuration object to pass to `zooming`.                                   | `{}`                                                                                                 |

Example usage in `docusaurus.config.js`:

```js
  themeConfig: {
    zooming: {
      selector: '.markdown :not(em) > img',
      delay: 500,
      background: {
        light: 'rgba(101,108,133,0.8)',
        dark: 'rgba(9,10,17,0.8)'
      },
      options: {
        enableGrab: false,
        // See the docs of zooming for all available options: https://github.com/francoischalifour/medium-zoom#usage
      }
    }
  }
```

import path from 'path';
import validatePeerDependencies from 'validate-peer-dependencies';

validatePeerDependencies(__dirname);

module.exports = function () {
  return {
    name: 'docusaurus-plugin-zooming',

    getClientModules() {
      return [path.resolve(__dirname, './zooming')];
    },
  };
};

import siteConfig from '@generated/docusaurus.config';
import Zooming from 'zooming'

const { themeConfig } = siteConfig;

export default (function () {
    if (typeof window === 'undefined') {
        return null;
    }

    const  {zooming: defaultParams} = themeConfig;

    const selector = defaultParams?.selector || '.markdown img';
    const delay = defaultParams?.delay || 500;
    let zoomingOptions = defaultParams?.options || {};

    const zooming = new Zooming();

    const setZoomingConfig = () => {
        const isDarkMode = document.querySelector('html[data-theme="dark"]');

        zoomingOptions.bgColor = isDarkMode
        ? defaultParams?.background?.dark || 'rgb(50, 50, 50, 0.9)'
        : defaultParams?.background?.light || 'rgb(255, 255, 255, 0.9)';

        zooming.config(zoomingOptions);
    };

    // First load
    setTimeout(()=> {
        zooming.listen(selector);

        setZoomingConfig();
    }, delay);

    // Update on theme change
    const observer = new MutationObserver(function () {
        if (!zooming) {
            return;
        }

        setZoomingConfig();
    });

    observer.observe(document.querySelector('html'), {
        attributes: true,
        attributeFilter: ['data-theme'],
    });  

    // Update on route change
    return {
        onRouteUpdate() {
          setTimeout(() => {
            if (!zooming) {
                return;
            }

            zooming.listen(selector);

            setZoomingConfig();
          }, delay);
        },
      };
})();
